sql.where:
r.is_deleted = 0

    AND r.course_id = #{q.courseId}


    AND r.uploader_id = #{q.uploaderId}


    AND r.type = #{q.type}


    AND r.visibility = #{q.visibility}


    AND r.status = #{q.status}


    AND (r.title LIKE CONCAT('%', #{q.keyword}, '%')
    OR r.description LIKE CONCAT('%', #{q.keyword}, '%'))




    AND (
        r.visibility = 'PUBLIC'


            OR r.uploader_id = #{q.currentUserId}

            OR (r.visibility = 'COURSE_ONLY' AND EXISTS (
                    SELECT 1 FROM course_member cm
                    WHERE cm.course_id = r.course_id
                      AND cm.user_id = #{q.currentUserId}
                ))

            OR EXISTS (
                SELECT 1 FROM course c2
                WHERE c2.id = r.course_id
                  AND c2.owner_id = #{q.currentUserId}
            )

    )

mapper.select:
SELECT



ORDER BY r.created_at DESC, r.id DESC
LIMIT #{q.offset}, #{q.pageSize}

mapper.update:
UPDATE resource
SET view_count = view_count + 1
WHERE id = #{id}

UPDATE resource
SET download_count = download_count + 1
WHERE id = #{id}

UPDATE resource
SET favorite_count = favorite_count + 1
WHERE id = #{id}

UPDATE resource
SET comment_count = comment_count + 1
WHERE id = #{id}

mapper.sql:
AND r.is_deleted = 0
AND r.status = 'PUBLISHED'
AND MATCH(r.title, r.description) AGAINST(#{q.keyword} IN BOOLEAN MODE)

    AND r.course_id = #{q.courseId}


    AND r.type = #{q.type}



    AND (
        r.visibility = 'PUBLIC'

            OR r.uploader_id = #{q.currentUserId}
            OR (r.visibility = 'COURSE_ONLY' AND EXISTS (
                    SELECT 1 FROM course_member cm
                    WHERE cm.course_id = r.course_id
                      AND cm.user_id = #{q.currentUserId}
                ))
            OR EXISTS (
                SELECT 1 FROM course c2
                WHERE c2.id = r.course_id AND c2.owner_id = #{q.currentUserId}
            )

    )
